// Chinese reference POIs are GCJ-02. The vector and imagery sources use WGS84.
export function gcjToWgs84([lng,lat]){const a=6378245,ee=.00669342162296594323,PI=Math.PI;let x=lng,y=lat;for(let i=0;i<4;i++){const u=x-105,v=y-35;let dlat=-100+2*u+3*v+.2*v*v+.1*u*v+.2*Math.sqrt(Math.abs(u)),dlng=300+u+2*v+.1*u*u+.1*u*v+.1*Math.sqrt(Math.abs(u));dlat+=(20*Math.sin(6*u*PI)+20*Math.sin(2*u*PI))*2/3;dlat+=(20*Math.sin(v*PI)+40*Math.sin(v/3*PI))*2/3;dlat+=(160*Math.sin(v/12*PI)+320*Math.sin(v*PI/30))*2/3;dlng+=(20*Math.sin(6*u*PI)+20*Math.sin(2*u*PI))*2/3;dlng+=(20*Math.sin(u*PI)+40*Math.sin(u/3*PI))*2/3;dlng+=(150*Math.sin(u/12*PI)+300*Math.sin(u/30*PI))*2/3;const rad=y/180*PI,magic=1-ee*Math.sin(rad)**2,sq=Math.sqrt(magic);dlng=dlng*180/(a/sq*Math.cos(rad)*PI);dlat=dlat*180/(a*(1-ee)/(magic*sq)*PI);x=lng-dlng;y=lat-dlat;}return[x,y];}
